import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.mrTIYZc5.js";const g=JSON.parse('{"title":"CLI Reference","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cli.md","filePath":"guide/cli.md"}'),o={name:"guide/cli.md"};function n(l,e,d,r,c,h){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="cli-reference" tabindex="-1">CLI Reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI Reference&quot;">​</a></h1><p>DSO is implemented as a native Docker CLI plugin. All interactions are performed via the <code>docker dso</code> command space.</p><hr><h2 id="command-up" tabindex="-1">Command: <code>up</code> <a class="header-anchor" href="#command-up" aria-label="Permalink to &quot;Command: `up`&quot;">​</a></h2><p>Synchronizes secrets and initializes a Docker Compose stack.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dso</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dso.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p><strong>Mechanics:</strong></p><ol><li><strong>Pre-flight</strong>: Parses <code>dso.yaml</code> and establishes a connection to the <code>dso-agent</code> via the Unix socket.</li><li><strong>Resolution</strong>: Fetches the latest secret values from the configured provider (AWS/Azure/Vault).</li><li><strong>Injection</strong>: Maps secret values to the environment of services defined in <code>docker-compose.yml</code>.</li><li><strong>Execution</strong>: Calls <code>docker compose up</code> with the enriched environment.</li></ol><p><strong>Common Flags:</strong></p><ul><li><code>-d, --detach</code>: Run containers in the background.</li><li><code>-c, --config</code>: Path to a custom <code>dso.yaml</code> (Default: <code>./dso.yaml</code>).</li><li><code>-f, --file</code>: Path to a custom <code>docker-compose.yml</code>.</li></ul><hr><h2 id="command-validate" tabindex="-1">Command: <code>validate</code> <a class="header-anchor" href="#command-validate" aria-label="Permalink to &quot;Command: `validate`&quot;">​</a></h2><p>Performs a structural and connectivity check on your configuration without starting any containers.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dso</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dso.yaml</span></span></code></pre></div><p><strong>Mechanics:</strong></p><ol><li><strong>Schema Check</strong>: Validates the <code>dso.yaml</code> syntax against the official JSON schema.</li><li><strong>Provider Probe</strong>: Attempts to authenticate with the cloud provider (AWS/Huawei/Vault) to verify IAM/Permissions.</li><li><strong>Mapping Audit</strong>: Checks if all environment variables mapped in <code>dso.yaml</code> exist in the target <code>docker-compose.yml</code>.</li></ol><hr><h2 id="command-down" tabindex="-1">Command: <code>down</code> <a class="header-anchor" href="#command-down" aria-label="Permalink to &quot;Command: `down`&quot;">​</a></h2><p>Stops the stack and performs a secure memory purge.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dso</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [compose-args...]</span></span></code></pre></div><p><strong>Mechanics:</strong></p><ol><li><strong>Termination</strong>: Calls <code>docker compose down</code> to stop and remove containers.</li><li><strong>Purge</strong>: Signals the <code>dso-agent</code> to flush the sensitive secret cache from its process memory.</li></ol><hr><h2 id="command-fetch" tabindex="-1">Command: <code>fetch</code> <a class="header-anchor" href="#command-fetch" aria-label="Permalink to &quot;Command: `fetch`&quot;">​</a></h2><p>Resolves and displays a specific secret (for debugging purposes).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dso</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">secret-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p><strong>Usage:</strong> Use this command to verify that your host has the correct IAM permissions or API access to reach the vault before launching a full stack. <strong>Note</strong>: Secret values are masked in the terminal output to prevent &quot;shoulder surfing&quot; leaks.</p><hr><h2 id="command-watch" tabindex="-1">Command: <code>watch</code> <a class="header-anchor" href="#command-watch" aria-label="Permalink to &quot;Command: `watch`&quot;">​</a></h2><p>Starts the Watcher Engine in foreground mode.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dso</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> watch</span></span></code></pre></div><p><strong>Usage:</strong> Ideal for debugging rotation strategies and SIGHUP signals. The command streams real-time reconciliation logs, showing exactly when a secret drift is detected and how the Reloader Controller responds.</p><hr><h2 id="command-version" tabindex="-1">Command: <code>version</code> <a class="header-anchor" href="#command-version" aria-label="Permalink to &quot;Command: `version`&quot;">​</a></h2><p>Displays the DSO binary version and build metadata.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dso</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span></code></pre></div><hr><h2 id="global-configuration-resolution" tabindex="-1">Global Configuration Resolution <a class="header-anchor" href="#global-configuration-resolution" aria-label="Permalink to &quot;Global Configuration Resolution&quot;">​</a></h2><p>DSO resolves its configuration using the following priority:</p><ol><li>Explicit flag via <code>--config</code>.</li><li>Environment variable <code>DSO_CONFIG</code>.</li><li>Local file <code>./dso.yaml</code>.</li><li>System-wide file <code>/etc/dso/dso.yaml</code>.</li></ol><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><strong><a href="/docs/guide/architecture.html">System Architecture</a></strong>: Learn how the CLI interacts with the Agent.</li><li><strong><a href="/docs/guide/configuration.html">Configuration Reference</a></strong>: Detailed <code>dso.yaml</code> schema.</li><li><strong><a href="/docs/guide/security.html">Security Model</a></strong>: How the CLI-to-Agent socket is protected.</li></ul>',42)])])}const m=s(o,[["render",n]]);export{g as __pageData,m as default};
